def get_meta_refresh(text, baseurl='', encoding='utf-8', ignore_tags=()):
    for m in _meta_re.finditer(text):
        tag = m.group(0)
        if ignore_tags:
            # crude: skip if refresh meta appears inside an ignored element
            prefix = text[:m.start()]
            for t in ignore_tags:
                opens = len(re.findall(r'<%s[\s>]' % t, prefix, re.I))
                closes = len(re.findall(r'</%s\s*>' % t, prefix, re.I))
